import { Page1Action } from '../../page1/types/Page1Types'
import { Page4ExecutionReceipt } from './Page4RouteExecutionModule'
import { Page4PlannedTask } from './Page4OpenClawPlanQaModule'

export interface Page4RegistryMethodDeps {
  normalizeMethodName: (raw: string) => string
  isAllowedMethodName: (raw: string) => boolean
  extractDestNode: (text: string) => string
  isValidGridId: (id: string) => boolean
  routeWithReplanAndWaitArrival: (dest: string) => Promise<Array<Page4ExecutionReceipt>>
  mapActionToken: (actionText: string) => Page1Action | undefined
  rememberSafePointFromStore: () => void
  onAction: (action: Page1Action) => Promise<void>
  setLastAction: (action: Page1Action) => void
  actionName: (action: Page1Action) => string
  setAutoFollowEnabled: (enabled: boolean) => void
  setRealSendEnabled: (enabled: boolean) => void
  speakText: (text: string) => Promise<boolean>
  getUndoTarget: () => string
  buildCameraFrameSummaryText: () => string
  buildStatusSummaryText: () => string
  buildVisionSummaryText: () => string
  buildCommSummaryText: () => string
  buildVideoSummaryText: () => string
  setRecognitionEnabled: (enabled: boolean) => void
  setAutoReportEnabled: (enabled: boolean) => void
  setVisionMode: (mode: 'traffic' | 'barrier') => boolean
  setAdaptiveStrategy: (mode: 'normal' | 'weak' | 'night') => boolean
  callTabletCompanion: (
    action: string,
    args: Record<string, Object | string | number | boolean | undefined>
  ) => Promise<{ ok: boolean, summary: string }>
  callPcToolGateway: (
    toolName: string,
    args: Record<string, Object | string | number | boolean | undefined>
  ) => Promise<{ ok: boolean, summary: string }>
  isAllowedPcExecCmd: (cmd: string) => boolean
  buildReceipt: (taskText: string, sent: boolean, done: boolean) => Page4ExecutionReceipt
}

export class Page4RegistryMethodModule {
  static parseMethodBooleanArg(
    args: Record<string, Object | string | number | boolean | undefined>,
    key: string
  ): boolean | undefined {
    const v: Object | string | number | boolean | undefined = args[key]
    if (typeof v === 'boolean') return v
    const s: string = String(v ?? '').trim().toLowerCase()
    if (s === 'true' || s === '1' || s === 'on' || s === 'yes') return true
    if (s === 'false' || s === '0' || s === 'off' || s === 'no') return false
    return undefined
  }

  static async executeRegistryMethod(
    task: Page4PlannedTask,
    deps: Page4RegistryMethodDeps
  ): Promise<Array<Page4ExecutionReceipt>> {
    const name: string = deps.normalizeMethodName(String(task.methodName ?? ''))
    const args: Record<string, Object | string | number | boolean | undefined> = task.methodArgs ?? {}
    const out: Array<Page4ExecutionReceipt> = []
    if (!deps.isAllowedMethodName(name)) {
      out.push(deps.buildReceipt(`未注册方法:${name}`, false, false))
      return out
    }
    if (name === 'start_manual_route') {
      const destRaw: string = String(args['dest'] ?? args['destNodeId'] ?? '').trim().toUpperCase()
      const dest: string = destRaw.length > 0 ? destRaw : deps.extractDestNode(String(args['text'] ?? ''))
      if (!deps.isValidGridId(dest)) return [deps.buildReceipt(`start_manual_route 参数错误 dest=${destRaw}`, false, false)]
      return await deps.routeWithReplanAndWaitArrival(dest)
    }
    if (name === 'send_action') {
      const actionToken: string = String(args['action'] ?? '').trim()
      const action: Page1Action | undefined = deps.mapActionToken(actionToken)
      if (typeof action === 'undefined') return [deps.buildReceipt(`send_action 参数错误 action=${actionToken}`, false, false)]
      deps.rememberSafePointFromStore()
      await deps.onAction(action)
      deps.setLastAction(action)
      return [deps.buildReceipt(deps.actionName(action), true, true)]
    }
    if (name === 'set_auto_follow') {
      const enabled: boolean | undefined = this.parseMethodBooleanArg(args, 'enabled')
      if (typeof enabled === 'undefined') return [deps.buildReceipt('set_auto_follow 参数错误 enabled', false, false)]
      deps.setAutoFollowEnabled(enabled)
      return [deps.buildReceipt(enabled ? '自动跟随开启' : '自动跟随关闭', true, true)]
    }
    if (name === 'set_send_mode') {
      const mode: string = String(args['mode'] ?? '').trim().toUpperCase()
      if (mode !== 'REAL_SEND' && mode !== 'DRY_RUN') return [deps.buildReceipt(`set_send_mode 参数错误 mode=${mode}`, false, false)]
      deps.setRealSendEnabled(mode === 'REAL_SEND')
      return [deps.buildReceipt(mode === 'REAL_SEND' ? '真车模式' : '仿真模式', true, true)]
    }
    if (name === 'speak_text') {
      const text: string = String(args['text'] ?? '').trim()
      if (text.length <= 0) return [deps.buildReceipt('speak_text 参数错误 text为空', false, false)]
      const content: string = text.length > 80 ? text.substring(0, 80) : text
      const ok: boolean = await deps.speakText(content)
      return [deps.buildReceipt(`语音播报:${content}`, ok, ok)]
    }
    if (name === 'undo_to_safe_point') {
      let stopOk: boolean = false
      try {
        await deps.onAction(Page1Action.STOP)
        deps.setLastAction(Page1Action.STOP)
        out.push(deps.buildReceipt('撤销-停止', true, true))
        stopOk = true
      } catch (e) {
        const msg: string = e instanceof Error ? e.message : 'stop failed'
        out.push(deps.buildReceipt(`撤销-停止失败(${msg})`, false, false))
      }
      const target: string = deps.getUndoTarget()
      if (stopOk && deps.isValidGridId(target)) {
        const backReceipts: Array<Page4ExecutionReceipt> = await deps.routeWithReplanAndWaitArrival(target)
        for (let i: number = 0; i < backReceipts.length; i++) out.push(backReceipts[i])
      } else if (stopOk) out.push(deps.buildReceipt('撤销-回安全点(未记录安全点)', false, false))
      return out
    }
    if (name === 'get_camera_frame') return [deps.buildReceipt(deps.buildCameraFrameSummaryText(), true, true)]
    if (name === 'query_status') return [deps.buildReceipt(deps.buildStatusSummaryText(), true, true)]
    if (name === 'query_vision') return [deps.buildReceipt(deps.buildVisionSummaryText(), true, true)]
    if (name === 'query_comm') return [deps.buildReceipt(deps.buildCommSummaryText(), true, true)]
    if (name === 'query_video') return [deps.buildReceipt(deps.buildVideoSummaryText(), true, true)]
    if (name === 'set_recognition') {
      const enabled: boolean | undefined = this.parseMethodBooleanArg(args, 'enabled')
      if (typeof enabled === 'undefined') return [deps.buildReceipt('set_recognition 参数错误 enabled', false, false)]
      deps.setRecognitionEnabled(enabled)
      return [deps.buildReceipt(enabled ? '识别已开启' : '识别已关闭', true, true)]
    }
    if (name === 'set_auto_report') {
      const enabled: boolean | undefined = this.parseMethodBooleanArg(args, 'enabled')
      if (typeof enabled === 'undefined') return [deps.buildReceipt('set_auto_report 参数错误 enabled', false, false)]
      deps.setAutoReportEnabled(enabled)
      return [deps.buildReceipt(enabled ? '自动回传已开启' : '自动回传已关闭', true, true)]
    }
    if (name === 'set_vision_mode') {
      const mode: string = String(args['mode'] ?? '').trim().toLowerCase()
      if (mode === 'traffic' && deps.setVisionMode('traffic')) return [deps.buildReceipt('视觉模型已切换为 traffic', true, true)]
      if ((mode === 'barrier' || mode === 'yolov26barrier') && deps.setVisionMode('barrier')) return [deps.buildReceipt('视觉模型已切换为 yolov26barrier', true, true)]
      return [deps.buildReceipt(`set_vision_mode 参数错误 mode=${mode}`, false, false)]
    }
    if (name === 'set_adaptive_strategy') {
      const mode: string = String(args['mode'] ?? '').trim().toLowerCase()
      if (!deps.setAdaptiveStrategy(mode as 'normal' | 'weak' | 'night')) return [deps.buildReceipt(`set_adaptive_strategy 参数错误 mode=${mode}`, false, false)]
      return [deps.buildReceipt(mode === 'normal' ? '策略已切换为常规' : '策略已切换为弱网/夜间', true, true)]
    }
    if (name === 'tablet_set_alarm') {
      const hour: number = Math.trunc(Number(String(args['hour'] ?? '').trim()))
      const minute: number = Math.trunc(Number(String(args['minute'] ?? '').trim()))
      const label: string = String(args['label'] ?? '').trim()
      if (!Number.isFinite(hour) || !Number.isFinite(minute) || hour < 0 || hour > 23 || minute < 0 || minute > 59) {
        return [deps.buildReceipt('tablet_set_alarm 参数错误 hour/minute', false, false)]
      }
      const r = await deps.callTabletCompanion('set_alarm', { hour, minute, label })
      return [deps.buildReceipt(r.summary, r.ok, r.ok)]
    }
    if (name === 'tablet_open_app') {
      const bundleName: string = String(args['bundleName'] ?? args['bundle'] ?? '').trim()
      if (bundleName.length <= 0) return [deps.buildReceipt('tablet_open_app 参数错误 bundleName为空', false, false)]
      const r = await deps.callTabletCompanion('open_app', { bundleName })
      return [deps.buildReceipt(r.summary, r.ok, r.ok)]
    }
    if (name === 'tablet_list_alarm') {
      const r = await deps.callTabletCompanion('list_alarm', {})
      return [deps.buildReceipt(r.summary, r.ok, r.ok)]
    }
    if (name === 'tablet_start_ability') {
      const bundleName: string = String(args['bundleName'] ?? args['bundle'] ?? '').trim()
      const abilityName: string = String(args['abilityName'] ?? '').trim()
      const paramsRaw: Object | string | number | boolean | undefined = args['parameters']
      const parameters: Record<string, Object | string | number | boolean | undefined> =
        typeof paramsRaw === 'object' && paramsRaw !== null ? (paramsRaw as Record<string, Object | string | number | boolean | undefined>) : {}
      if (bundleName.length <= 0) return [deps.buildReceipt('tablet_start_ability 参数错误 bundleName为空', false, false)]
      const r = await deps.callTabletCompanion('start_ability', { bundleName, abilityName, parameters })
      return [deps.buildReceipt(r.summary, r.ok, r.ok)]
    }
    if (name === 'tablet_open_url') {
      const url: string = String(args['url'] ?? '').trim()
      if (url.length <= 0) return [deps.buildReceipt('tablet_open_url 参数错误 url为空', false, false)]
      const r = await deps.callTabletCompanion('open_url', { url })
      return [deps.buildReceipt(r.summary, r.ok, r.ok)]
    }
    if (name === 'read_file') {
      const path: string = String(args['path'] ?? '').trim()
      if (path.length <= 0) return [deps.buildReceipt('read_file 参数错误 path为空', false, false)]
      if (path.endsWith('/') || path.endsWith('\\')) return [deps.buildReceipt(`read_file 参数错误 path疑似目录:${path}`, false, false)]
      const r = await deps.callPcToolGateway('read_file', { path })
      return [deps.buildReceipt(r.summary, r.ok, r.ok)]
    }
    if (name === 'process_list') {
      const r = await deps.callPcToolGateway('process_list', {})
      return [deps.buildReceipt(r.summary, r.ok, r.ok)]
    }
    if (name === 'exec_cmd') {
      const cmd: string = String(args['cmd'] ?? args['command'] ?? '').trim()
      if (cmd.length <= 0) return [deps.buildReceipt('exec_cmd 参数错误 cmd为空', false, false)]
      if (!deps.isAllowedPcExecCmd(cmd)) return [deps.buildReceipt(`exec_cmd 被策略拒绝:${cmd}`, false, false)]
      const r = await deps.callPcToolGateway('exec_cmd', { cmd })
      return [deps.buildReceipt(r.summary, r.ok, r.ok)]
    }
    return [deps.buildReceipt(`未实现方法:${name}`, false, false)]
  }
}

import { Page1Action } from '../../page1/types/Page1Types'
import { Page4PlannedTask } from '../modules/Page4OpenClawPlanQaModule'

export interface Page4TaskParseDeps {
  extractDestNode: (text: string) => string
  isValidGridId: (id: string) => boolean
  resolveActionByText: (lower: string) => Page1Action | undefined
  looksLikeCaptureFrameIntent: (lower: string) => boolean
  containsAny: (text: string, keys: Array<string>) => boolean
}

export class Page4OrchestrationLayer {
  static actionName(action: Page1Action): string {
    if (action === Page1Action.GO) return '前进'
    if (action === Page1Action.BACK) return '后退'
    if (action === Page1Action.LEFT) return '左转'
    if (action === Page1Action.RIGHT) return '右转'
    if (action === Page1Action.UTURN) return '掉头'
    if (action === Page1Action.STOP) return '停止'
    if (action === Page1Action.SCRAM) return '紧急停止'
    if (action === Page1Action.TFTA) return 'TFTA'
    return '动作'
  }

  static resolveActionByText(
    textLower: string,
    lastAction: Page1Action | undefined,
    containsAny: (text: string, keys: Array<string>) => boolean
  ): Page1Action | undefined {
    if (containsAny(textLower, ['再来一次', '重复上一动作', '继续刚才动作', 'repeat'])) return lastAction
    if (containsAny(textLower, ['紧急停止', '急停', 'scram'])) return Page1Action.SCRAM
    if (containsAny(textLower, ['停止', '停车', 'stop'])) return Page1Action.STOP
    if (containsAny(textLower, ['前进', '向前', 'go'])) return Page1Action.GO
    if (containsAny(textLower, ['后退', '倒车', 'back'])) return Page1Action.BACK
    if (containsAny(textLower, ['左转'])) return Page1Action.LEFT
    if (containsAny(textLower, ['右转'])) return Page1Action.RIGHT
    if (containsAny(textLower, ['掉头'])) return Page1Action.UTURN
    return undefined
  }

  static looksLikeCaptureFrameIntent(
    textLower: string,
    containsAny: (text: string, keys: Array<string>) => boolean
  ): boolean {
    return containsAny(textLower, [
      '获取当前摄像头画面',
      '获取当前画面',
      '抓取当前画面',
      '读取当前画面',
      '保存当前画面',
      '给我当前画面',
      '看一下当前画面',
      'camera frame',
      'current frame',
      'capture frame'
    ])
  }

  static splitPromptToClauses(text: string): Array<string> {
    const src: string = text
      .replace(/然后|接着|随后|并且|并且再|同时|接下来|再去|再到/g, '|')
      .replace(/[，,；;。.!！?？\n]/g, '|')
    const raw: Array<string> = src.split('|')
    const out: Array<string> = []
    for (let i: number = 0; i < raw.length; i++) {
      const one: string = raw[i].trim()
      if (one.length > 0) out.push(one)
    }
    return out
  }

  static parseTaskFromClause(clause: string, deps: Page4TaskParseDeps): Page4PlannedTask | undefined {
    const lower: string = clause.toLowerCase()
    const dest: string = deps.extractDestNode(clause)
    if (dest.length > 0 && deps.isValidGridId(dest)) return { kind: 'route', destNodeId: dest }

    const action: Page1Action | undefined = deps.resolveActionByText(lower)
    if (action !== undefined) return { kind: 'action', action: action }

    if (deps.containsAny(lower, ['开启自动跟随', '打开自动跟随', '自动跟随开启', '自动驾驶开启'])) return { kind: 'auto_follow', enabled: true }
    if (deps.containsAny(lower, ['关闭自动跟随', '停止自动跟随', '自动跟随关闭', '自动驾驶关闭'])) return { kind: 'auto_follow', enabled: false }
    if (deps.containsAny(lower, ['开启真车模式', '真车模式', 'real_send'])) return { kind: 'send_mode', mode: 'REAL_SEND' }
    if (deps.containsAny(lower, ['开启仿真模式', '仿真模式', 'dry_run', '关闭真车模式'])) return { kind: 'send_mode', mode: 'DRY_RUN' }
    if (deps.looksLikeCaptureFrameIntent(lower)) return { kind: 'capture_frame' }
    if (deps.containsAny(lower, ['查询状态', '状态', 'status'])) return { kind: 'query_status' }
    if (deps.containsAny(lower, ['识别状态', '视觉状态', '识别结果', 'vision'])) return { kind: 'query_vision' }
    if (deps.containsAny(lower, ['网络', '通信'])) return { kind: 'query_comm' }
    if (deps.containsAny(lower, ['视频', '相机'])) return { kind: 'query_video' }
    return undefined
  }

  static parseLocalPlannedTasks(text: string, deps: Page4TaskParseDeps): Array<Page4PlannedTask> {
    const clauses: Array<string> = this.splitPromptToClauses(text)
    const out: Array<Page4PlannedTask> = []
    for (let i: number = 0; i < clauses.length; i++) {
      const task: Page4PlannedTask | undefined = this.parseTaskFromClause(clauses[i], deps)
      if (!task) continue
      out.push(task)
    }
    return out
  }

  static looksLikeMultiTask(text: string, containsAny: (text: string, keys: Array<string>) => boolean): boolean {
    const x: string = text.trim()
    if (x.length <= 0) return false
    if (this.splitPromptToClauses(x).length >= 2) return true
    return containsAny(x, ['然后', '接着', '并且', '同时', '再', '随后', ';', '；', ',', '，'])
  }

  static looksLikeControlIntent(
    text: string,
    lower: string,
    extractDestNode: (text: string) => string,
    containsAny: (text: string, keys: Array<string>) => boolean
  ): boolean {
    if (text.trim().length <= 0) return false
    if (this.looksLikeMultiTask(text, containsAny)) return true
    if (extractDestNode(text).length > 0) return true
    const keywords: Array<string> = [
      '导航', '前往', '去', '到',
      '返仓', '回仓', '返航', '回基地', '回中心', '回物流中心', '回快递点', '回仓库', '返仓库',
      '前进', '后退', '左转', '右转', '掉头', '停止', '急停', '刹车',
      '自动跟随', '自动驾驶', '真车模式', '仿真模式', 'real_send', 'dry_run',
      '撤销', '回到安全点',
      '抓拍', '截图', '拍照', '相机', '视频',
      '查询状态', '状态', '识别', '视觉', '通信', '网络',
      '读取文件', '读文件', '文件内容', '进程列表', '查询进程', '执行命令', '命令行', 'process', 'read_file', 'exec_cmd'
    ]
    return containsAny(lower, keywords)
  }
}

export interface Page4QueueState {
  queuedPromptCount: number
  queuedPromptCap: number
  assistantBusy: boolean
  promptQueueTail: Promise<void>
}

export interface Page4QueueHooks {
  pushAssistant: (text: string) => void
  submitPrompt: (text: string, fromQueue: boolean, source: string) => Promise<void>
}

export class Page4InputQueueModule {
  static async enqueuePrompt(
    raw: string,
    source: string,
    state: Page4QueueState,
    hooks: Page4QueueHooks
  ): Promise<Page4QueueState> {
    const text: string = raw.trim()
    if (text.length <= 0) return state
    if (state.queuedPromptCount >= state.queuedPromptCap) {
      hooks.pushAssistant(`任务队列已满(${state.queuedPromptCap})，请稍后再试。`)
      return state
    }
    const next: Page4QueueState = {
      queuedPromptCount: state.queuedPromptCount + 1,
      queuedPromptCap: state.queuedPromptCap,
      assistantBusy: state.assistantBusy,
      promptQueueTail: state.promptQueueTail
    }
    if (next.queuedPromptCount > 1) {
      hooks.pushAssistant(`已加入队列，前方还有 ${next.queuedPromptCount - 1} 条。`)
    }
    const runOne = async (): Promise<void> => {
      next.assistantBusy = true
      try {
        await hooks.submitPrompt(text, true, source)
      } finally {
        next.queuedPromptCount = Math.max(0, next.queuedPromptCount - 1)
        if (next.queuedPromptCount <= 0) next.assistantBusy = false
      }
    }
    next.promptQueueTail = next.promptQueueTail.then(runOne, runOne)
    await next.promptQueueTail
    return next
  }
}

import { Page1Action } from '../../page1/types/Page1Types'

export type Page4PlannedTaskKind =
  'route' |
  'action' |
  'auto_follow' |
  'send_mode' |
  'capture_frame' |
  'undo' |
  'method' |
  'query_status' |
  'query_vision' |
  'query_comm' |
  'query_video'

export interface Page4PlannedTask {
  kind: Page4PlannedTaskKind
  destNodeId?: string
  action?: Page1Action
  enabled?: boolean
  mode?: 'REAL_SEND' | 'DRY_RUN'
  methodName?: string
  methodArgs?: Record<string, Object | string | number | boolean | undefined>
}

export class Page4OpenClawPlanQaModule {
  static mapActionToken(actionText: string): Page1Action | undefined {
    const t: string = actionText.trim().toUpperCase()
    if (t === 'GO' || t === 'FORWARD') return Page1Action.GO
    if (t === 'BACK' || t === 'BACKWARD') return Page1Action.BACK
    if (t === 'LEFT' || t === 'TURN_LEFT') return Page1Action.LEFT
    if (t === 'RIGHT' || t === 'TURN_RIGHT') return Page1Action.RIGHT
    if (t === 'UTURN' || t === 'U_TURN') return Page1Action.UTURN
    if (t === 'STOP') return Page1Action.STOP
    if (t === 'SCRAM' || t === 'ESTOP') return Page1Action.SCRAM
    return undefined
  }

  static normalizeMethodName(raw: string): string {
    const name: string = raw.trim().toLowerCase()
    if (name === 'undo_last_action') return 'undo_to_safe_point'
    if (name === 'capture_current_frame') return 'get_camera_frame'
    return name
  }

  static isAllowedMethodName(raw: string): boolean {
    const name: string = this.normalizeMethodName(raw)
    const allowed: Array<string> = [
      'start_manual_route','send_action','set_auto_follow','set_send_mode','speak_text','undo_to_safe_point',
      'get_camera_frame','query_status','query_vision','query_comm','query_video','read_file','process_list',
      'exec_cmd','set_recognition','set_auto_report','set_vision_mode','set_adaptive_strategy','tablet_set_alarm',
      'tablet_open_app','tablet_list_alarm','tablet_start_ability','tablet_open_url'
    ]
    for (let i: number = 0; i < allowed.length; i++) if (allowed[i] === name) return true
    return false
  }

  static extractJsonObject(text: string): string {
    const src: string = text.trim()
    if (src.length <= 0) return ''
    const codeBlock: RegExpMatchArray | null = src.match(/```(?:json)?\s*([\s\S]*?)```/i)
    const body: string = codeBlock && codeBlock.length > 1 ? codeBlock[1].trim() : src
    const start: number = body.indexOf('{')
    const end: number = body.lastIndexOf('}')
    if (start < 0 || end <= start) return ''
    return body.substring(start, end + 1)
  }

  static mapOpenClawPlan(text: string): Array<Page4PlannedTask> {
    const jsonText: string = this.extractJsonObject(text)
    if (jsonText.length <= 0) return []
    try {
      const root: Record<string, Object | string | number | boolean | Array<Object>> =
        JSON.parse(jsonText) as Record<string, Object | string | number | boolean | Array<Object>>
      const arr: Array<Record<string, Object | string | number | boolean>> = Array.isArray(root['tasks'])
        ? (root['tasks'] as Array<Record<string, Object | string | number | boolean>>)
        : []
      const out: Array<Page4PlannedTask> = []
      for (let i: number = 0; i < arr.length; i++) {
        const t: Record<string, Object | string | number | boolean> = arr[i]
        const typeText: string = String(t['type'] ?? '').trim().toLowerCase()
        if (typeText === 'route') { const dest: string = String(t['dest'] ?? '').trim().toUpperCase(); if (dest.length > 0) out.push({ kind: 'route', destNodeId: dest }); continue }
        if (typeText === 'action') { const action = this.mapActionToken(String(t['action'] ?? '')); if (action !== undefined) out.push({ kind: 'action', action }); continue }
        if (typeText === 'auto_follow') { const v: string = String(t['enabled'] ?? '').trim().toLowerCase(); if (v === 'true' || v === '1' || v === 'on') out.push({ kind: 'auto_follow', enabled: true }); else if (v === 'false' || v === '0' || v === 'off') out.push({ kind: 'auto_follow', enabled: false }); continue }
        if (typeText === 'send_mode') { const v: string = String(t['mode'] ?? '').trim().toUpperCase(); if (v === 'REAL_SEND' || v === 'DRY_RUN') out.push({ kind: 'send_mode', mode: v as 'REAL_SEND' | 'DRY_RUN' }); continue }
        if (typeText === 'capture_frame') { out.push({ kind: 'capture_frame' }); continue }
        if (typeText === 'undo') { out.push({ kind: 'undo' }); continue }
        if (typeText === 'query_status') { out.push({ kind: 'query_status' }); continue }
        if (typeText === 'query_vision') { out.push({ kind: 'query_vision' }); continue }
        if (typeText === 'query_comm') { out.push({ kind: 'query_comm' }); continue }
        if (typeText === 'query_video') { out.push({ kind: 'query_video' }); continue }
        if (typeText === 'method' || typeText === 'call') {
          const name: string = this.normalizeMethodName(String(typeText === 'method' ? (t['name'] ?? '') : (t['method'] ?? '')))
          const argsRaw: Object | string | number | boolean | undefined = typeText === 'method' ? t['args'] : t['params']
          const args: Record<string, Object | string | number | boolean | undefined> =
            typeof argsRaw === 'object' && argsRaw !== null
              ? (argsRaw as Record<string, Object | string | number | boolean | undefined>)
              : {}
          if (!this.isAllowedMethodName(name)) continue
          out.push({ kind: 'method', methodName: name, methodArgs: args })
          continue
        }
      }
      return out
    } catch (_) {
      return []
    }
  }
}

